// Month and date labels for the public summaries generated by
// backend/utils/compute_analytics.py (ward "at a glance" and monthly reports).
// Months are "YYYY-MM" keys and dates are "YYYY-MM-DD" Chicago calendar days,
// so they are formatted in UTC to avoid shifting across a day boundary.

const longMonthFormat = new Intl.DateTimeFormat("en-US", {
  month: "long",
  year: "numeric",
  timeZone: "UTC",
});
const monthNameFormat = new Intl.DateTimeFormat("en-US", { month: "long", timeZone: "UTC" });
const shortMonthNameFormat = new Intl.DateTimeFormat("en-US", { month: "short", timeZone: "UTC" });
const longDateFormat = new Intl.DateTimeFormat("en-US", { dateStyle: "long", timeZone: "UTC" });

function monthStart(month: string): Date {
  const [year, monthNumber] = month.split("-").map(Number);
  return new Date(Date.UTC(year, monthNumber - 1, 1));
}

/** "September 2026" for "2026-09". */
export function formatLongMonth(month: string): string {
  return longMonthFormat.format(monthStart(month));
}

/** "Sep" for "2026-09". */
export function formatShortMonthName(month: string): string {
  return shortMonthNameFormat.format(monthStart(month));
}

/** "April to September 2026", or "November 2025 to April 2026" across years. */
export function formatMonthRange(firstMonth: string, lastMonth: string): string {
  if (firstMonth === lastMonth) {
    return formatLongMonth(firstMonth);
  }
  const sameYear = firstMonth.slice(0, 4) === lastMonth.slice(0, 4);
  const start = sameYear
    ? monthNameFormat.format(monthStart(firstMonth))
    : formatLongMonth(firstMonth);
  return `${start} to ${formatLongMonth(lastMonth)}`;
}

/** "October 13, 2026" for "2026-10-13". */
export function formatLongDate(isoDate: string): string {
  const [year, month, day] = isoDate.split("-").map(Number);
  return longDateFormat.format(new Date(Date.UTC(year, month - 1, day)));
}

/** The "YYYY-MM" month of a "YYYY-MM-DD" date. */
export function monthOfDate(isoDate: string): string {
  return isoDate.slice(0, 7);
}
